  fields: [
    { key: 'payments', label: 'Payments', from: 'rent_payments' },
    { key: 'collected', label: 'Rent Collected', from: 'rent_payments.amount', type: 'money' },
    { key: 'billed', label: 'Billed', from: 'rent_invoices.total_amount', type: 'money' },
    { key: 'rate', label: 'Collected %', calc: 'round(collected / billed * 100)' },
    { key: 'share', label: 'Share of Income', calc: 'share(collected)' },
  ],

  remarks: [
    { if: 'collected == 0', tone: 'bad', title: 'No income', say: '{label} received no rent in this period.' },
    { if: 'rate !== null && rate < 70', tone: 'watch', title: 'Low collection', say: '{label}: only {rate}% of the {billed} billed was collected.' },
    { if: 'true', tone: 'good', title: 'Performing', say: '{label}: {collected} collected, {share}% of total income.' },
  ],

  headline: '{label} collected the most: {collected} from {payments} payments, {share}% of the total.',
